module ring_counter (
    input wire clk,
    input wire reset,
    output reg [7:0] out
);

    parameter INITIAL_STATE = 8'b0000_0001;

    reg [7:0] counter;

    always @(posedge clk or posedge (reset)) begin
        if (reset) begin
            counter <= INITIAL_STATE;
        end else begin
            counter <= {counter[6:0], counter[7]};
        end
    end

    assign out = counter;

endmodule
